        animate={inView ? { opacity: 1, y: 0 } : {}}
        transition={{ duration: 0.8, ease: "easeOut" }}
    >
        <span className="mt-36 font-extrabold text-4xl lg:text-5xl whitespace-nowrap block">SANSKRITI CHAUHAN</span>
    </motion.div>
        </>
    )
